using System;\nusing System.Collections.Concurrent;\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace MagnumOpus.Core\n{\n    public enum TransactionStatus { Pending, Confirmed, Failed }\n\n    public record Transaction(string Id, string From, string To, decimal Amount, string Token, DateTime Timestamp);\n\n    public record ProcessedTransaction(string Id, TransactionStatus Status, string? Reason = null);\n\n    public interface ITransactionValidator\n    {\n        Task<bool> ValidateAsync(Transaction tx);\n    }\n\n    public class BasicValidator : ITransactionValidator\n    {\n        public Task<bool> ValidateAsync(Transaction tx) =>\n            Task.FromResult(tx.Amount > 0 && !string.IsNullOrWhiteSpace(tx.From) && !string.IsNullOrWhiteSpace(tx.To));\n    }\n\n    public class TransactionProcessor\n    {\n        private readonly ITransactionValidator _validator;\n        private readonly ConcurrentQueue<Transaction> _queue = new();\n        private readonly ConcurrentDictionary<string, ProcessedTransaction> _store = new();\n        private readonly CancellationTokenSource _cts = new();\n        private readonly TimeSpan _processingDelay = TimeSpan.FromMilliseconds(200);\n        private readonly int _maxParallelism = Environment.ProcessorCount;\n\n        public event Action<ProcessedTransaction>? OnTransactionProcessed;\n\n        public TransactionProcessor(ITransactionValidator? validator = null)\n        {\n            _validator = validator ?? new BasicValidator();\n            StartWorkers();\n        }\n\n        private void StartWorkers()\n        {\n            for (int i = 0; i < _maxParallelism; i++)\n            {\n                Task.Run(ProcessLoopAsync);\n            }\n        }\n\n        private async Task ProcessLoopAsync()\n        {\n            while (!_cts.IsCancellationRequested)\n            {\n                if (_queue.TryDequeue(out var tx))\n                {\n                    var result = await ProcessSingleAsync(tx);\n                    _store[tx.Id] = result;\n                    OnTransactionProcessed?.Invoke(result);\n                }\n                else\n                {\n                    await Task.Delay(50, _cts.Token).ConfigureAwait(false);\n                }\n            }\n        }\n\n        private async Task<ProcessedTransaction> ProcessSingleAsync(Transaction tx)\n        {\n            try\n            {\n                var isValid = await _validator.ValidateAsync(tx);\n                if (!isValid)\n                    return new ProcessedTransaction(tx.Id, TransactionStatus.Failed, "Validation failed");\n\n                // Simulate heavy cryptographic work\n                await Task.Delay(_processingDelay, _cts.Token).ConfigureAwait(false);\n                // In real engine, compute hash, update state, etc.\n                return new ProcessedTransaction(tx.Id, TransactionStatus.Confirmed);\n            }\n            catch (Exception ex)\n            {\n                return new ProcessedTransaction(tx.Id, TransactionStatus.Failed, ex.Message);\n            }\n        }\n\n        public void Enqueue(Transaction tx)\n        {\n            if (string.IsNullOrWhiteSpace(tx.Id))\n                throw new ArgumentException("Transaction must have an Id", nameof(tx));\n            _queue.Enqueue(tx);\n        }\n\n        public bool TryGetResult(string txId, out ProcessedTransaction? result) =>\n            _store.TryGetValue(txId, out result);\n\n        public void Shutdown()\n        {\n            _cts.Cancel();\n        }\n    }\n}\n